/* ---------- quantifiable kinds: compute + tolerance (validate recomputes) ---------- */
var QK={
 npv:{u:'$',d:2,tol:0.02,label:'net present value',f:function(i){var s=0;for(var t=0;t<i.cfs.length;t++)s+=i.cfs[t]/Math.pow(1+i.rate,t+1);return s-i.inv;}},
 eoq:{u:'units',d:1,tol:0.06,label:'economic order quantity',f:function(i){return Math.sqrt(2*i.D*i.S/i.H);}},
 oee:{u:'%',d:2,tol:0.02,label:'overall equipment effectiveness',f:function(i){return i.a*i.p*i.q*100;}},
 eac:{u:'$',d:2,tol:0.06,label:'estimate at completion',f:function(i){return i.bac/(i.ev/i.ac);}},
 clv:{u:'$',d:2,tol:0.02,label:'customer lifetime value',f:function(i){return i.apv*i.freq*i.life;}},
 zscore:{u:'points',d:2,tol:0.02,label:'Altman Z-score',f:function(i){return 1.2*i.x1+1.4*i.x2+3.3*i.x3+0.6*i.x4+1.0*i.x5;}},
 dpmo:{u:'',d:1,tol:0.6,label:'defects per million opportunities',f:function(i){return i.defects*1e6/(i.units*i.opp);}},
 runway:{u:'months',d:1,tol:0.06,label:'cash runway',f:function(i){return i.cash/i.burn;}},
 dd:{u:'defects/KLOC',d:2,tol:0.02,label:'defect density',f:function(i){return i.defects/i.kloc;}},
 cacpay:{u:'months',d:1,tol:0.06,label:'CAC payback period',f:function(i){return i.cac/(i.arpa*i.margin);}},
 rop:{u:'units',d:0,tol:0.6,label:'reorder point',f:function(i){return i.d*i.lt;}},
 be:{u:'units',d:0,tol:0.6,label:'breakeven point',f:function(i){return i.fixed/(i.price-i.varc);}},
 wacc:{u:'%',d:3,tol:0.003,label:'weighted average cost of capital',f:function(i){return (i.wd*i.rd*(1-i.tax)+i.we*i.re)*100;}},
 pert:{u:'days',d:1,tol:0.06,label:'PERT expected duration',f:function(i){return (i.o+4*i.m+i.p)/6;}},
 emv:{u:'$',d:2,tol:0.02,label:'expected monetary value',f:function(i){return i.p*i.impact;}},
 wip:{u:'units',d:1,tol:0.06,label:'work in process (Little\'s law)',f:function(i){return i.throughput*i.ct;}}
};
function qinputs(kind,ranges,rnd){
  var o={};
  Object.keys(ranges).forEach(function(k){var r=ranges[k];o[k]=r.length===3?rf(rnd,r[0],r[1],r[2]):ri(rnd,r[0],r[1]);});
  if(kind==='npv'&&o.cf1!==undefined){o.cfs=[o.cf1,o.cf2,o.cf3];delete o.cf1;delete o.cf2;delete o.cf3;}
  return o;
}
function mkQuant(kind,ranges,rnd,note){
  var inputs=qinputs(kind,ranges,rnd);
  var res=+QK[kind].f(inputs).toFixed(QK[kind].d);
  var q={kind:kind,inputs:inputs,result:res,unit:QK[kind].u};
  if(note)q.note=note;
  return q;
}
function qline(q){return 'Inputs '+JSON.stringify(q.inputs)+' -> '+q.result+(q.unit?' '+q.unit:'');}
